# LLM 配置路由（config.py 简化版）
# resolved_llm：公开方法，实现核心业务逻辑
def resolved_llm(provider: str) -> dict:
    """将 provider 名称解析为统一的 {base_url, api_key, model, headers}"""
    if provider == "local":
        return {
            "base_url": "http://localhost:11434/v1",  # Ollama 本地模型
            "api_key": "not-needed",
            "model": os.getenv("LOCAL_MODEL", "qwen2.5:7b"),
            "headers": {}
        }
    elif provider == "deepseek":
        return {
            "base_url": "https://api.deepseek.com/v1",
            "api_key": os.environ["DEEPSEEK_API_KEY"],
            "model": os.getenv("DEEPSEEK_MODEL", "deepseek-chat"),
            "headers": {}
        }
    elif provider == "custom":
        return {
            "base_url": os.environ["CUSTOM_LLM_URL"],
            "api_key": os.environ.get("CUSTOM_LLM_KEY", ""),
            "model": os.getenv("CUSTOM_LLM_MODEL", "default"),
            "headers": json.loads(os.getenv("CUSTOM_LLM_HEADERS", "{}"))
        }
    # 所有 provider 最终归一化为相同的四元组结构
